function activeElementFingerprintFromSettle(ae) {
    if (!ae || typeof ae !== 'object') return 'null';
    return `${String(ae.tag || '').toUpperCase()}|${String(ae.dataTestId || '')}`;
}

/**
 * Bounded wait for a quiet shell before offline-kill Settings open (harness-only).
 * Reduces flapping between no-mount and mounted-selector mismatch by not clicking while layout/modals churn.
 */
async function settleOfflineKillShellBeforeSettingsOpen(pg, _testInfo) {
    const SETTLE_BUDGET_MS = 12000;
    const SETTLE_STABLE_GAP_MS = 380;
    const SETTLE_POLL_MS = 420;
    const collect = async () => {
        const inPage = await pg.evaluate(() => {
            const norm = (s) => (typeof s === 'string' ? s.trim().slice(0, 4000) : '');
            const rectVisible = (el) => {
                if (!(el instanceof Element)) return false;
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                return (
                    r.width > 0 &&
                    r.height > 0 &&
                    st.visibility !== 'hidden' &&
                    st.display !== 'none' &&
                    Number(st.opacity || '1') > 0
                );
            };
            const djb2 = (str) => {
                let h = 5381 >>> 0;
                for (let i = 0; i < str.length; i += 1) {
                    h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
                }
                return h.toString(16);
            };
            const bodySlice = norm(document.body.innerText || '').slice(0, 2400);
            const rootEl = document.getElementById('root');
            const rootSlice = rootEl ? norm(rootEl.innerText || '').slice(0, 900) : '';
            const openerBtns = Array.from(document.querySelectorAll('[data-testid="settings-open-btn"]'));
            const b0 = openerBtns[0] || null;
            const br = b0 ? rectVisible(b0) : false;
            const disabled = b0 ? Boolean(b0.disabled) : true;
            const ariaDisabled = b0 ? b0.getAttribute('aria-disabled') : null;
            const drawers = document.querySelectorAll('[data-testid="settings-drawer"]');
            let openDrawerVisibleCount = 0;
            document.querySelectorAll('[data-testid="settings-drawer"][data-state="open"]').forEach((d) => {
                if (rectVisible(d)) openDrawerVisibleCount += 1;
            });
            const ae = document.activeElement;
            let blockingAriaModalVisible = 0;
            document.querySelectorAll('[aria-modal="true"]').forEach((el) => {
                if (rectVisible(el)) blockingAriaModalVisible += 1;
            });
            return {
                collectError: null,
                readyState: document.readyState || '',
                url: location.href,
                viewport: { width: window.innerWidth, height: window.innerHeight },
                bodyTextHash: djb2(bodySlice),
                bodyTextSample: bodySlice.slice(0, 220),
                rootTextHash: djb2(rootSlice),
                rootTextSample: rootSlice.slice(0, 220),
                drawerCount: drawers.length,
                openDrawerCount: document.querySelectorAll('[data-testid="settings-drawer"][data-state="open"]').length,
                openDrawerVisibleCount,
                settingsOpenBtnCount: openerBtns.length,
                settingsOpenerVisible: Boolean(b0 && br),
                settingsOpenerDisabled: disabled,
                settingsAriaDisabled: ariaDisabled,
                blockingAriaModalVisible,
                activeElement:
                    ae instanceof Element
                        ? {
                              tag: ae.tagName,
                              dataTestId: ae.getAttribute('data-testid') || '',
                          }
                        : null,
            };
        });
        const sessionModalVisible = await pg.getByTestId('session-modal').isVisible().catch(() => false);
        const paletteVisible = await pg.getByTestId('command-palette').isVisible().catch(() => false);
        return {
            ...inPage,
            sessionModalVisible,
            commandPaletteVisible: paletteVisible,
        };
    };
    const hardOk = (s) => {
        if (!s || s.collectError) return false;
        if (s.readyState !== 'complete') return false;
        if (Number(s.settingsOpenBtnCount) < 1 || !s.settingsOpenerVisible) return false;
        if (s.settingsOpenerDisabled || s.settingsAriaDisabled === 'true') return false;
        if (Number(s.openDrawerVisibleCount) > 0 || Number(s.openDrawerCount) > 0) return false;
        if (s.sessionModalVisible || s.commandPaletteVisible) return false;
        if (Number(s.blockingAriaModalVisible) > 0) return false;
        return true;
    };
    const started = Date.now();
    const first = await collect().catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e) }));
    const rtBefore = await collectSettingsRuntimeStateSnapshot(pg, 2000).catch((e) => ({
        collectError: e && e.message ? String(e.message) : String(e),
    }));
    await attachJsonSnapshot('offline-kill-open-settings-shell-settle-before.json', {
        classification: 'offline-kill-settings-open-shell-settle-before',
        ...offlineKillBudgetSnapshot(),
        shellSettleBudgetMs: SETTLE_BUDGET_MS,
        ...first,
        runtimeStateSummary: buildOfflineKillRuntimeStateSummary(rtBefore),
        ...rtBefore,
    });
    let last = first;
    let iterations = 0;
    while (Date.now() - started < SETTLE_BUDGET_MS) {
        iterations += 1;
        const a = await collect().catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e) }));
        last = a;
        if (!hardOk(a)) {
            await pg.waitForTimeout(SETTLE_POLL_MS).catch(() => {});
            continue;
        }
        await pg.waitForTimeout(SETTLE_STABLE_GAP_MS).catch(() => {});
        const b = await collect().catch((e) => ({ collectError: e && e.message ? String(e.message) : String(e) }));
        last = b;
        if (!hardOk(b)) {
            await pg.waitForTimeout(SETTLE_POLL_MS).catch(() => {});
            continue;
        }
        const aeOk =
            activeElementFingerprintFromSettle(a.activeElement) === activeElementFingerprintFromSettle(b.activeElement);
        const textOk = a.bodyTextHash === b.bodyTextHash && a.rootTextHash === b.rootTextHash;
        const drawerOk =
            Number(a.drawerCount) === Number(b.drawerCount) &&
            Number(a.openDrawerCount) === Number(b.openDrawerCount) &&
            Number(a.openDrawerVisibleCount) === Number(b.openDrawerVisibleCount);
        if (aeOk && textOk && drawerOk) {
            const rtAfter = await collectSettingsRuntimeStateSnapshot(pg, 2200).catch((e) => ({
                collectError: e && e.message ? String(e.message) : String(e),
            }));
            await attachJsonSnapshot('offline-kill-open-settings-shell-settle-after.json', {
                classification: 'offline-kill-settings-open-shell-settle-after',
                settled: true,
                ...offlineKillBudgetSnapshot(),
                shellSettleElapsedMs: Date.now() - started,
                shellSettleIterations: iterations,
                ...b,
                runtimeStateSummary: buildOfflineKillRuntimeStateSummary(rtAfter),
                ...rtAfter,
            });
            /* eslint-disable no-console -- surfaced for CI raw logs */
            console.log(
                `offline-kill-shell-settle=ok iterations=${iterations} elapsedMs=${Date.now() - started} activeFp=${activeElementFingerprintFromSettle(b.activeElement)}`,
            );
            /* eslint-enable no-console */
            appendOfflineKillCiSummary(
                `- \`offline-kill-shell-settle\` = \`ok\` (iterations=\`${iterations}\`, elapsedMs=\`${Date.now() - started}\`)`,
            );
            return;
        }
        await pg.waitForTimeout(SETTLE_POLL_MS).catch(() => {});
    }
    const rtFail = await collectSettingsRuntimeStateSnapshot(pg, 2200).catch((e) => ({
        collectError: e && e.message ? String(e.message) : String(e),
    }));
    await attachJsonSnapshot('offline-kill-open-settings-shell-settle-after.json', {
        classification: 'offline-kill-settings-open-shell-settle-after',
        settled: false,
        reason: 'settings-open-shell-not-settled',
        ...offlineKillBudgetSnapshot(),
        shellSettleElapsedMs: Date.now() - started,
        shellSettleIterations: iterations,
        ...last,
        runtimeStateSummary: buildOfflineKillRuntimeStateSummary(rtFail),
        ...rtFail,
    });

