function activeElementFingerprintFromSettle(ae) {
    if (!ae || typeof ae !== 'object') return 'null';
    return `${String(ae.tag || '').toUpperCase()}|${String(ae.dataTestId || '')}`;
}

function buildOfflineKillShellSettleHardGateResults(s) {
    if (!s || s.collectError) {
        return { collectError: Boolean(s && s.collectError), allOk: false };
    }
    const gates = {
        readyStateComplete: s.readyState === 'complete',
        settingsOpenerPresent: Number(s.settingsOpenBtnCount) >= 1,
        settingsOpenerVisible: Boolean(s.settingsOpenerVisible),
        settingsOpenerEnabled: !s.settingsOpenerDisabled && s.settingsAriaDisabled !== 'true',
        noOpenDrawer:
            Number(s.openDrawerVisibleCount) === 0 &&
            Number(s.openDrawerCount) === 0,
        noSessionModal: !s.sessionModalVisible,
        noCommandPalette: !s.commandPaletteVisible,
        noBlockingAriaModal: Number(s.blockingAriaModalVisible) === 0,
    };
    const allOk = Object.values(gates).every(Boolean);
    return { ...gates, allOk };
}

function buildOfflineKillShellSettleTextCompare(a, b) {
    const rawTextStable =
        a.rawBodyTextHash === b.rawBodyTextHash && a.rawRootTextHash === b.rawRootTextHash;
    const normalizedTextStable =
        a.normalizedBodyTextHash === b.normalizedBodyTextHash &&
        a.normalizedRootTextHash === b.normalizedRootTextHash;
    const volA = Array.isArray(a.volatileTextPatternsDetected) ? a.volatileTextPatternsDetected : [];
    const volB = Array.isArray(b.volatileTextPatternsDetected) ? b.volatileTextPatternsDetected : [];
    const volatileTextPatternsDetected = Array.from(new Set([...volA, ...volB])).sort();
    return {
        rawBodyTextHashBefore: a.rawBodyTextHash,
        rawBodyTextHashAfter: b.rawBodyTextHash,
        rawRootTextHashBefore: a.rawRootTextHash,
        rawRootTextHashAfter: b.rawRootTextHash,
        normalizedBodyTextHashBefore: a.normalizedBodyTextHash,
        normalizedBodyTextHashAfter: b.normalizedBodyTextHash,
        normalizedRootTextHashBefore: a.normalizedRootTextHash,
        normalizedRootTextHashAfter: b.normalizedRootTextHash,
        rawTextStable,
        normalizedTextStable,
        textHashIgnoredBecauseVolatile: !rawTextStable && normalizedTextStable,
        volatileTextPatternsDetected,
    };
}

function shellSettleModalCandidatesSummary(s) {
    if (!s || s.collectError) return { sessionModalVisible: null, commandPaletteVisible: null, blockingAriaModalVisible: null };
    return {
        sessionModalVisible: Boolean(s.sessionModalVisible),
        commandPaletteVisible: Boolean(s.commandPaletteVisible),
        blockingAriaModalVisible: Number(s.blockingAriaModalVisible) || 0,
    };
}

function shellSettleSettingsOpenBtnSummary(s) {
    if (!s || s.collectError) {
        return { count: null, visible: null, disabled: null, ariaDisabled: null };
    }
    return {
        count: Number(s.settingsOpenBtnCount) || 0,
        visible: Boolean(s.settingsOpenerVisible),
        disabled: Boolean(s.settingsOpenerDisabled),
        ariaDisabled: s.settingsAriaDisabled == null ? null : String(s.settingsAriaDisabled),
    };
}

