function summarizeOfflineKillProbeEventSequence(events) {
    if (!Array.isArray(events)) return { count: 0, types: [], defaultPreventedAny: false };
    const types = [];
    let defaultPreventedAny = false;
    for (let i = 0; i < events.length; i += 1) {
        const e = events[i];
        if (!e || typeof e !== 'object') continue;
        if (e.type) types.push(String(e.type));
        if (e.defaultPrevented === true) defaultPreventedAny = true;
    }
    return { count: events.length, types, defaultPreventedAny };
}

function summarizeOfflineKillProbeMutationSequence(mutations) {
    if (!Array.isArray(mutations)) return { count: 0, kinds: [] };
    const kinds = mutations.map((m) => (m && m.kind ? String(m.kind) : '')).filter(Boolean);
    return { count: mutations.length, kinds };
}

