                const st = window.getComputedStyle(btn);
                const cx = r.left + Math.min(Math.max(r.width / 2, 1), r.width);
                const cy = r.top + Math.min(Math.max(r.height / 2, 1), r.height);
                const rectVisible = () =>
                    r.width > 0 &&
                    r.height > 0 &&
                    st.visibility !== 'hidden' &&
                    st.display !== 'none' &&
                    Number(st.opacity || '1') > 0;
