# Small bundle: .md / .json / .txt under test-results (avoids huge binary dirs). Also include Playwright
# trace.zip for failing E2E folders (e.g. offline-kill local-only-bridge posture) so open-settings
# investigations keep trace without uploading full html/png/webm trees (ENOBUFS risk).
- name: Bundle minimal Verify UI diagnostics
  if: always()
  shell: pwsh
  run: |
    New-Item -ItemType Directory -Force -Path verify-ui-minimal | Out-Null
    "verify-ui minimal bundle created at $(Get-Date -Format o)" | Out-File -Encoding utf8 verify-ui-minimal/verify-ui-minimal-marker.txt

    if (Test-Path -LiteralPath test-results) {
      $base = (Resolve-Path -LiteralPath test-results).Path
      Get-ChildItem -LiteralPath test-results -Recurse -File | Where-Object {
        $ext = $_.Extension.ToLowerInvariant()
        if ($ext -in @(".md", ".json", ".txt")) {
          return $true
        }
        # trace.zip only (Playwright); skip other zips to keep artifact size bounded.
        if ($ext -eq ".zip" -and $_.Name -ieq "trace.zip") {
          return $true
        }
        return $false
      } | ForEach-Object {
        $relative = [System.IO.Path]::GetRelativePath($base, $_.FullName)
        $dest = Join-Path (Join-Path verify-ui-minimal "test-results") $relative
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
        Copy-Item -LiteralPath $_.FullName -Destination $dest -Force
      }

      $patterns = @(
        "*offline-kill-open-settings*.json",
        "*opener-binding*.json",
        "*handler-trace*.json",
        "*first-click-commit-probe*.json",
        "*handler-not-committing*.json",
        "*offline-kill-early-open-settings-failed*.json"
      )
      Write-Host "=== Minimal bundle: diagnostic JSON / trace match check ==="
      foreach ($pat in $patterns) {
        $hits = @(Get-ChildItem -LiteralPath test-results -Recurse -File -Filter $pat -ErrorAction SilentlyContinue)
        Write-Host ("pattern {0} -> {1} file(s) under test-results" -f $pat, $hits.Count)
        foreach ($h in $hits | Select-Object -First 20) {
          Write-Host ("  " + $h.FullName)
        }
      }
      $traceZips = @(Get-ChildItem -LiteralPath test-results -Recurse -File -Filter "trace.zip" -ErrorAction SilentlyContinue)
      Write-Host ("trace.zip under test-results: {0}" -f $traceZips.Count)
      foreach ($t in $traceZips | Select-Object -First 20) {
        Write-Host ("  " + $t.FullName)
      }
      Write-Host "=== End diagnostic match check ==="
    }

