function summarizeElementForSettingsOpenTrace(el) {
    if (!el || el.nodeType !== 1) return null;
    try {
        const tid = el.getAttribute('data-testid') || '';
        const text = String(el.innerText || '')
            .trim()
            .slice(0, 120);
        const parts = [];
        let n = el;
        for (let i = 0; i < 8 && n && n.nodeType === 1; i += 1) {
            const tn = String(n.tagName || 'DIV').toLowerCase();
            const dt = n.getAttribute('data-testid');
            parts.unshift(dt ? `${tn}[data-testid="${String(dt).slice(0, 80)}"]` : tn);
            n = n.parentElement;
        }
        return {
            tagName: el.tagName,
            testid: tid,
            dataTestId: tid,
            id: String(el.id || '').slice(0, 120),
            className: String(el.className || '').slice(0, 200),
            role: String(el.getAttribute('role') || '').slice(0, 64),
            ariaLabel: String(el.getAttribute('aria-label') || '').slice(0, 200),
            text,
            disabled: 'disabled' in el ? Boolean(el.disabled) : false,
            path: parts.join(' > '),
        };
    } catch {
        return null;
    }
