/**
 * Build optional metadata for ShellContext.closeSettings(source, meta) from a DOM event.
 * @param {{ callsiteLabel?: string, nativeEvent?: Event|null }} opts
 */
export function buildSettingsCloseTraceMeta(opts = {}) {
    const out = {};
    if (opts && typeof opts.callsiteLabel === 'string' && opts.callsiteLabel.trim()) {
        out.callsiteLabel = opts.callsiteLabel.trim().slice(0, 160);
    }
    const ev = opts && opts.nativeEvent;
    if (!ev || typeof ev !== 'object') return out;
    try {
        if (typeof ev.type === 'string') out.eventType = ev.type.slice(0, 48);
        if (typeof ev.key === 'string') out.eventKey = ev.key.slice(0, 48);
        const t = ev.target;
        if (t && typeof t === 'object' && t.nodeType === 1) {
            if (t.tagName) out.targetTag = String(t.tagName).slice(0, 48);
            if (t.id) out.targetId = String(t.id).slice(0, 120);
            const tid = t.getAttribute && t.getAttribute('data-testid');
            if (tid) out.targetTestId = String(tid).slice(0, 120);
        }
        const ct = ev.currentTarget;
        if (ct && typeof ct === 'object' && ct.nodeType === 1 && ct.tagName) {
            out.currentTargetTag = String(ct.tagName).slice(0, 48);
        }
    } catch {
        /* ignore */
    }
    return out;
}

